Body:
It actually shows up, when you define the model(s)! Good hint @ShahriarKh 
For the docs and ppl looking for multiple custom provider setup in opencode:
```
{
  "$schema": "https://opencode.ai/config.json",
  "plugin": [
    "opencode-lmstudio@latest"
  ],
  "provider": {
    "lmstudio": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "LM Studio (local)",
      "options": {
        "baseURL": "http://localhost:1234/v1"
      }
    },
    "mbpconn": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "LM Studio (remote)",
      "options": {
        "baseURL": "http://<fqdn-of-host>:1234/v1",
        "apiKey": "apiKey-but-oc-might-ask-u-for-one-anyway"
      },
      "models": {
        "qwen/qwen3.6-35b-a3b":  {
          "name": "Qwen3.5 35b a3b 8bit"
        },
        "qwen/qwen3.6-27b": {
          "name": "Qwen 3.6 27b 8bit"
        }
      }
    }
  }
```
